public int maxProfit(int[] prices) {
    int minPrice = Integer.MAX_VALUE;   // cheapest buy seen so far
    int best = 0;
    for (int p : prices) {
        best = Math.max(best, p - minPrice);   // sell today
        minPrice = Math.min(minPrice, p);      // or remember a cheaper buy
    }
    return best;
}

public int majorityElement(int[] nums) {
    int candidate = 0, count = 0;
    for (int x : nums) {
        if (count == 0) candidate = x;          // start a new candidate
        count += (x == candidate) ? 1 : -1;     // vote for, or cancel out
    }
    return candidate;
}

